% Monte Carlo Reachable Workspace for Phantom X Pincher
clear; clc; close all;

%No. of samples
N = 50000;

% Joint limits
theta_min = deg2rad(-150); 
theta_max = deg2rad(150); 

% Generate N random samples for all 4 joints using uniform distribution
joint_samples = theta_min + (theta_max - theta_min) * rand(N, 4);

%arrays for (x,y,z) coordinates
X = zeros(N, 1);
Y = zeros(N, 1);
Z = zeros(N, 1); %[output:07e7f545]

for k = 1:N
   [X(k), Y(k), Z(k)] = pincherFK(joint_samples(k,:));
end

%Maximum Horizontal Reach
horizontal_reach = sqrt(X.^2 + Y.^2);
max_reach = max(horizontal_reach); %[output:95366ce5] %[output:559905c6]
fprintf('Maximum Horizontal Reach: %.2f mm\n', max_reach); %[output:6ae97530] %[output:1e710df2]
%Plotting

% Figure 1: Isometric View
figure('Name', 'Isometric View of Workspace'); %[output:9570a4eb]
% scatter3 draws the point cloud. Marker face alpha adds transparency.
scatter3(X, Y, Z, 2, 'b', 'filled', 'MarkerFaceAlpha', 0.2); %[output:9570a4eb]
title('Phantom X Pincher Reachable Workspace (Isometric)'); %[output:9570a4eb]
xlabel('X (mm)'); ylabel('Y (mm)'); zlabel('Z (mm)'); %[output:9570a4eb]
axis equal; grid on; view(3); % view(3) sets standard 3D isometric view %[output:9570a4eb]

% Figure 2: Top View (X-Y Projection)
figure('Name', 'Top View of Workspace (X-Y Projection)'); %[output:99e62dd9]
scatter(X, Y, 2, 'r', 'filled', 'MarkerFaceAlpha', 0.2); %[output:99e62dd9]
title(sprintf('Workspace Projection (X-Y Plane)\nMax Reach: %.2f mm', max_reach)); %[output:99e62dd9]
xlabel('X (mm)'); ylabel('Y (mm)'); %[output:99e62dd9]
axis equal; grid on; %[output:99e62dd9]

% Draw a circle indicating the maximum horizontal reach boundary
hold on; %[output:99e62dd9]
th_circle = linspace(0, 2*pi, 100);
plot(max_reach*cos(th_circle), max_reach*sin(th_circle), 'k--', 'LineWidth', 1.5); %[output:99e62dd9]
legend('End-Effector Positions', 'Max Reach Boundary', 'Location', 'best'); %[output:99e62dd9]
hold off; %[output:99e62dd9]

